import Firecrawl from '@mendable/firecrawl-js';
import { sanitizeText, sanitizeUrl } from './sanitize';

let client: Firecrawl | null = null;

function getClient(): Firecrawl {
  const apiKey = process.env.FIRECRAWL_API_KEY;
  if (!apiKey) {
    throw new Error('FIRECRAWL_API_KEY is not configured');
  }
  if (!client) {
    client = new Firecrawl({ apiKey });
  }
  return client;
}

export interface ScrapeResult {
  markdown: string;
  title?: string;
  description?: string;
  sourceUrl: string;
}

export async function scrapeWebsite(url: string): Promise<ScrapeResult> {
  const safeUrl = sanitizeUrl(url);
  const fc = getClient();

  const result = await fc.scrapeUrl(safeUrl, {
    formats: ['markdown'],
    onlyMainContent: true,
  });

  if (!result.success) {
    throw new Error(
      typeof result.error === 'string' ? result.error : 'Firecrawl scrape failed'
    );
  }

  const markdown = sanitizeText(result.markdown ?? '', 30000);

  if (!markdown || markdown.length < 50) {
    throw new Error(
      'Could not extract enough content from this URL. Try a different page.'
    );
  }

  return {
    markdown,
    title: result.metadata?.title,
    description: result.metadata?.description,
    sourceUrl: safeUrl,
  };
}

import { sanitizeText } from './sanitize';
import type { PlatformId } from './platforms';

export interface N8nGeneratePayload {
  websiteUrl: string;
  scrapedContent: string;
  userPrompt: string;
  optimizedPrompt: string;
  platform: PlatformId;
  userId: string;
  executionId: string;
}

export interface N8nGenerateResponse {
  success: boolean;
  executionId?: string;
  userId?: string;
  platform?: string;
  platformName?: string;
  websiteUrl?: string;
  summary?: string;
  content?: string;
  qualityScore?: number;
  wordCount?: number;
  generatedAt?: string;
  error?: string;
}

export async function triggerN8nWorkflow(
  payload: N8nGeneratePayload
): Promise<N8nGenerateResponse> {
  const webhookUrl = process.env.N8N_WEBHOOK_URL;
  const apiKey = process.env.N8N_API_KEY;

  if (!webhookUrl) {
    throw new Error('N8N_WEBHOOK_URL is not configured');
  }

  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
  };

  if (apiKey) {
    headers['Authorization'] = `Bearer ${apiKey}`;
    headers['X-N8N-API-KEY'] = apiKey;
  }

  const controller = new AbortController();
  const timeout = setTimeout(
    () => controller.abort(),
    Number(process.env.N8N_TIMEOUT_MS ?? 120000)
  );

  let lastError: Error | null = null;
  const maxRetries = Number(process.env.N8N_MAX_RETRIES ?? 2);

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      const res = await fetch(webhookUrl, {
        method: 'POST',
        headers,
        body: JSON.stringify({
          websiteUrl: payload.websiteUrl,
          scrapedContent: sanitizeText(payload.scrapedContent, 30000),
          userPrompt: sanitizeText(payload.userPrompt, 4000),
          optimizedPrompt: sanitizeText(payload.optimizedPrompt, 5000),
          platform: payload.platform,
          userId: payload.userId,
          executionId: payload.executionId,
        }),
        signal: controller.signal,
      });

      if (!res.ok) {
        const text = await res.text();
        throw new Error(`n8n workflow failed (${res.status}): ${text.slice(0, 500)}`);
      }

      const data = (await res.json()) as N8nGenerateResponse;
      clearTimeout(timeout);

      if (!data.success && !data.content) {
        throw new Error(data.error ?? 'n8n returned empty content');
      }

      return {
        ...data,
        content: data.content ? sanitizeText(data.content, 20000) : undefined,
        summary: data.summary ? sanitizeText(data.summary, 5000) : undefined,
      };
    } catch (err) {
      lastError = err instanceof Error ? err : new Error(String(err));
      if (attempt < maxRetries) {
        await new Promise((r) => setTimeout(r, 1000 * (attempt + 1)));
      }
    }
  }

  clearTimeout(timeout);
  throw lastError ?? new Error('n8n workflow failed after retries');
}

export const PLATFORMS = [
  { id: 'linkedin', label: 'LinkedIn' },
  { id: 'twitter', label: 'X (Twitter)' },
  { id: 'instagram', label: 'Instagram' },
  { id: 'facebook', label: 'Facebook' },
  { id: 'reddit', label: 'Reddit' },
  { id: 'medium', label: 'Medium' },
  { id: 'devto', label: 'Dev.to' },
  { id: 'threads', label: 'Threads' },
  { id: 'youtube', label: 'YouTube Community' },
  { id: 'producthunt', label: 'Product Hunt' },
] as const;

export type PlatformId = (typeof PLATFORMS)[number]['id'];

const PLATFORM_GUIDES: Record<PlatformId, string> = {
  linkedin:
    'Write a professional LinkedIn post with structured insights, industry relevance, and a clear CTA. Use line breaks. 3-5 hashtags at the end.',
  twitter:
    'Write a punchy X/Twitter post under 280 characters. Sharp insight, optional question, 1-2 hashtags max.',
  instagram:
    'Write an Instagram caption with a strong hook, emoji where natural, line breaks, and 10-15 hashtags in a separate block.',
  facebook:
    'Write a friendly Facebook post that encourages comments. Conversational tone, 2-4 hashtags.',
  reddit:
    'Write a Reddit post (title + body). Authentic, value-first, no salesy tone. Use markdown if helpful.',
  medium:
    'Write a Medium-style teaser: compelling headline, subtitle, and opening paragraphs that draw readers in.',
  devto:
    'Write a Dev.to post intro: developer-focused, accessible, with suggested tags at the end.',
  threads:
    'Write a casual Threads micro-post. Concise, conversational, 2-3 hashtags.',
  youtube:
    'Write a YouTube Community post that sparks discussion. Engaging and concise.',
  producthunt:
    'Write a Product Hunt launch-style post: problem, solution, unique value. Exciting but credible.',
};

export function optimizePromptForPlatform(
  userPrompt: string,
  platform: PlatformId
): string {
  const guide = PLATFORM_GUIDES[platform] ?? PLATFORM_GUIDES.linkedin;
  return `${userPrompt.trim()}\n\n[Platform optimization: ${guide}]`;
}

export function isValidPlatform(value: string): value is PlatformId {
  return PLATFORMS.some((p) => p.id === value);
}

import { Queue, Worker, Job } from 'bullmq';
import { getRedis } from './redis';

const QUEUE_NAME = 'socialflow-generate';

export interface QueueJobData {
  userId: string;
  executionId: string;
  websiteUrl: string;
  scrapedContent: string;
  userPrompt: string;
  optimizedPrompt: string;
  platform: string;
}

let queue: Queue<QueueJobData> | null = null;

export function getGenerateQueue(): Queue<QueueJobData> | null {
  const redis = getRedis();
  if (!redis) return null;

  if (!queue) {
    queue = new Queue<QueueJobData>(QUEUE_NAME, {
      connection: { host: redis.options.host, port: redis.options.port },
    });
  }
  return queue;
}

export async function enqueueGeneration(
  data: QueueJobData
): Promise<{ queued: boolean; jobId?: string }> {
  const q = getGenerateQueue();
  if (!q) return { queued: false };

  const job = await q.add('generate', data, {
    attempts: 3,
    backoff: { type: 'exponential', delay: 2000 },
    removeOnComplete: 100,
    removeOnFail: 50,
  });

  return { queued: true, jobId: job.id };
}

export type JobProcessor = (job: Job<QueueJobData>) => Promise<void>;

export function startWorker(processor: JobProcessor): Worker<QueueJobData> | null {
  const redis = getRedis();
  if (!redis) return null;

  return new Worker<QueueJobData>(QUEUE_NAME, processor, {
    connection: { host: redis.options.host, port: redis.options.port },
    concurrency: 2,
  });
}

import { connectDB } from './db';
import mongoose from 'mongoose';

interface RateLimitDoc {
  key: string;
  count: number;
  windowStart: Date;
}

const RateLimitSchema = new mongoose.Schema<RateLimitDoc>({
  key: { type: String, required: true, unique: true },
  count: { type: Number, default: 0 },
  windowStart: { type: Date, default: Date.now },
});

const RateLimitModel =
  mongoose.models.RateLimit ??
  mongoose.model<RateLimitDoc>('RateLimit', RateLimitSchema);

export async function checkRateLimit(
  key: string
): Promise<{ allowed: boolean; remaining: number; resetMs: number }> {
  await connectDB();

  const points = Number(process.env.RATE_LIMIT_POINTS ?? 10);
  const durationSec = Number(process.env.RATE_LIMIT_DURATION_SEC ?? 3600);
  const windowMs = durationSec * 1000;
  const now = new Date();

  let doc = await RateLimitModel.findOne({ key });

  if (!doc || now.getTime() - doc.windowStart.getTime() > windowMs) {
    doc = await RateLimitModel.findOneAndUpdate(
      { key },
      { count: 1, windowStart: now },
      { upsert: true, new: true }
    );
    return { allowed: true, remaining: points - 1, resetMs: windowMs };
  }

  if (doc.count >= points) {
    const resetMs =
      windowMs - (now.getTime() - doc.windowStart.getTime());
    return { allowed: false, remaining: 0, resetMs: Math.max(resetMs, 0) };
  }

  doc = await RateLimitModel.findOneAndUpdate(
    { key },
    { $inc: { count: 1 } },
    { new: true }
  );

  return {
    allowed: true,
    remaining: points - (doc?.count ?? 1),
    resetMs: windowMs - (now.getTime() - (doc?.windowStart.getTime() ?? 0)),
  };
}

import Redis from 'ioredis';

let redis: Redis | null = null;

export function getRedis(): Redis | null {
  const url = process.env.REDIS_URL;
  if (!url) return null;

  if (!redis) {
    redis = new Redis(url, {
      maxRetriesPerRequest: 3,
      lazyConnect: true,
    });
  }
  return redis;
}

export async function cacheGet<T>(key: string): Promise<T | null> {
  const r = getRedis();
  if (!r) return null;
  try {
    const val = await r.get(key);
    return val ? (JSON.parse(val) as T) : null;
  } catch {
    return null;
  }
}

export async function cacheSet(
  key: string,
  value: unknown,
  ttlSeconds = 3600
): Promise<void> {
  const r = getRedis();
  if (!r) return;
  try {
    await r.setex(key, ttlSeconds, JSON.stringify(value));
  } catch {
    // cache is optional
  }
}

export function sanitizeText(input: string, maxLength = 50000): string {
  return input
    .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
    .replace(/<[^>]+>/g, '')
    .trim()
    .slice(0, maxLength);
}

export function sanitizeUrl(url: string): string {
  try {
    const parsed = new URL(url);
    if (!['http:', 'https:'].includes(parsed.protocol)) {
      throw new Error('Invalid protocol');
    }
    return parsed.toString();
  } catch {
    throw new Error('Invalid URL');
  }
}

import { connectDB } from './db';
import { User } from '@/models/User';
import { UsageAnalytics } from '@/models/UsageAnalytics';

export async function ensureUser(params: {
  clerkId: string;
  email: string;
  name: string;
  imageUrl?: string;
}) {
  await connectDB();
  const existing = await User.findOne({ clerkId: params.clerkId });
  if (existing) return existing;

  return User.create({
    clerkId: params.clerkId,
    email: params.email,
    name: params.name,
    imageUrl: params.imageUrl,
    credits: Number(process.env.DEFAULT_USER_CREDITS ?? 50),
    plan: 'free',
  });
}

export async function deductCredit(clerkId: string, amount = 1): Promise<boolean> {
  await connectDB();
  const user = await User.findOne({ clerkId });
  if (!user || user.credits < amount) return false;
  user.credits -= amount;
  await user.save();
  return true;
}

export async function trackUsage(
  userId: string,
  platform: string,
  creditsUsed = 1
) {
  await connectDB();
  const date = new Date().toISOString().slice(0, 10);

  await UsageAnalytics.findOneAndUpdate(
    { userId, date },
    {
      $inc: {
        generations: 1,
        creditsUsed,
        [`platforms.${platform}`]: 1,
      },
    },
    { upsert: true, new: true }
  );
}

import { z } from 'zod';
import { PLATFORMS } from './platforms';

const platformIds = PLATFORMS.map((p) => p.id) as [string, ...string[]];

export const generateRequestSchema = z.object({
  websiteUrl: z
    .string()
    .url('Please enter a valid URL')
    .max(2048)
    .refine((url) => /^https?:\/\//i.test(url), 'URL must use http or https'),
  userPrompt: z
    .string()
    .min(10, 'Prompt must be at least 10 characters')
    .max(4000, 'Prompt must be under 4000 characters'),
  platform: z.enum(platformIds),
});

export const crawlPreviewSchema = z.object({
  websiteUrl: z.string().url().max(2048),
});

export type GenerateRequest = z.infer<typeof generateRequestSchema>;

